"use strict";(function(){$.validator.addMethod("eitherrequired",function(n,t,i){return i.every(function(n){return n.value!==""})});$.validator.unobtrusive.adapters.add("eitherrequired",function(n){var t=$(n.form).find("#HandId")[0],i=$(n.form).find("#Nickname")[0],r=$(n.form).find("#Username")[0];n.rules.eitherrequired=[t,i,r];n.messages.eitherrequired=n.message})})();